CREATE OR REPLACE FUNCTION public.add_offices_to_fax_bulk(p_fax_received_id bigint, p_office_ids bigint[], p_assigned_by character varying DEFAULT NULL::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_office_id BIGINT;
  v_is_first BOOLEAN := TRUE;
  v_inserted_count INT := 0;
  v_primary_office_id BIGINT;
BEGIN
  -- 入力チェック
  IF p_fax_received_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', FALSE,
      'error', 'fax_received_id is required'
    );
  END IF;
  
  IF p_office_ids IS NULL OR array_length(p_office_ids, 1) IS NULL OR array_length(p_office_ids, 1) = 0 THEN
    RETURN jsonb_build_object(
      'success', TRUE,
      'fax_received_id', p_fax_received_id,
      'inserted_count', 0,
      'message', 'No offices to add'
    );
  END IF;
  
  -- 各事業所を登録
  FOREACH v_office_id IN ARRAY p_office_ids
  LOOP
    -- 事業所の存在確認
    IF NOT EXISTS (SELECT 1 FROM cm_kaipoke_other_office WHERE id = v_office_id) THEN
      CONTINUE;  -- 存在しない事業所はスキップ
    END IF;
    
    INSERT INTO cm_fax_received_offices (
      fax_received_id,
      office_id,
      is_primary,
      assigned_by,
      assigned_at
    ) VALUES (
      p_fax_received_id,
      v_office_id,
      v_is_first,  -- 最初の1件をprimaryに
      p_assigned_by,
      CASE WHEN p_assigned_by IS NOT NULL THEN NOW() ELSE NULL END
    )
    ON CONFLICT (fax_received_id, office_id) DO UPDATE SET
      is_primary = CASE WHEN v_is_first THEN TRUE ELSE cm_fax_received_offices.is_primary END,
      assigned_by = COALESCE(EXCLUDED.assigned_by, cm_fax_received_offices.assigned_by),
      assigned_at = COALESCE(EXCLUDED.assigned_at, cm_fax_received_offices.assigned_at);
    
    v_inserted_count := v_inserted_count + 1;
    
    -- 最初の事業所をcm_fax_received.office_idにも設定（後方互換）
    IF v_is_first THEN
      v_primary_office_id := v_office_id;
      
      UPDATE cm_fax_received
      SET 
        office_id = v_office_id,
        office_assigned_by = p_assigned_by,
        office_assigned_at = CASE WHEN p_assigned_by IS NOT NULL THEN NOW() ELSE NULL END,
        updated_at = NOW()
      WHERE id = p_fax_received_id;
      
      v_is_first := FALSE;
    END IF;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', TRUE,
    'fax_received_id', p_fax_received_id,
    'inserted_count', v_inserted_count,
    'primary_office_id', v_primary_office_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.add_pages_to_document(p_document_id bigint, p_page_ids bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_page_id BIGINT;
  v_max_order INT;
  v_page_order INT;
  v_added_count INT := 0;
BEGIN
  IF p_document_id IS NULL THEN
    RETURN jsonb_build_object('success', FALSE, 'error', 'document_id is required');
  END IF;
  
  IF p_page_ids IS NULL OR array_length(p_page_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('success', TRUE, 'document_id', p_document_id, 'added_pages', 0);
  END IF;
  
  -- 現在の最大順序を取得
  SELECT COALESCE(MAX(page_order), 0) INTO v_max_order
  FROM cm_fax_document_pages
  WHERE fax_document_id = p_document_id;
  
  v_page_order := v_max_order + 1;
  
  -- ページを追加
  FOREACH v_page_id IN ARRAY p_page_ids
  LOOP
    INSERT INTO cm_fax_document_pages (
      fax_document_id,
      fax_page_id,
      page_order
    ) VALUES (
      p_document_id,
      v_page_id,
      v_page_order
    )
    ON CONFLICT (fax_document_id, fax_page_id) DO NOTHING;
    
    IF FOUND THEN
      v_added_count := v_added_count + 1;
      v_page_order := v_page_order + 1;
    END IF;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', TRUE,
    'document_id', p_document_id,
    'added_pages', v_added_count
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.assign_user_to_shift(p_shift_id bigint, p_user_id text, p_role_code text DEFAULT NULL::text, p_accompany boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_shift         shift%rowtype;
  v_required      smallint;
  v_empty_idx     int := 0;
  v_candidate_idx int := 0;
  v_lowest_sort   bigint := null;
  v_level_sort    bigint;
  v_slot_idx      int;
  v_slot_names    text[] := array['staff_01','staff_02','staff_03'];
  v_slot_cols     text[] := array['staff_01_user_id','staff_02_user_id','staff_03_user_id'];
  v_role_cols     text[] := array['staff_01_role_code','staff_02_role_code','staff_03_role_code'];
  v_curr_user_id  text;
  v_level_sorts   bigint[] := array[NULL::bigint, NULL::bigint, NULL::bigint];
  v_decision      text := '';
  v_status        text := '';
  v_message       text := null;
begin
  -- 1) 対象行をロック取得
  select * into v_shift from public.shift where shift_id = p_shift_id for update;
  if not found then
    v_status  := 'error';
    v_message := 'shift not found';
    insert into public.shift_assign_log(shift_id, requested_user_id, accompany, decision, status, message)
    values (p_shift_id, p_user_id, p_accompany, 'not_found', v_status, v_message);
    return jsonb_build_object('status','error','message',v_message);
  end if;

  -- 2) 既に本人が入っているなら何もしない
  if v_shift.staff_01_user_id = p_user_id
     or v_shift.staff_02_user_id = p_user_id
     or v_shift.staff_03_user_id = p_user_id then
    v_status   := 'noop';
    v_decision := 'already_assigned';
    insert into public.shift_assign_log(
      shift_id, requested_user_id, accompany, required_staff_count,
      staff_01_user_id, staff_02_user_id, staff_03_user_id,
      empty_idx, candidate_idx, lowest_sort, decision, status, message
    ) values (
      p_shift_id, p_user_id, p_accompany, v_shift.required_staff_count,
      v_shift.staff_01_user_id, v_shift.staff_02_user_id, v_shift.staff_03_user_id,
      0, 0, null, v_decision, v_status, 'already assigned'
    );
    return jsonb_build_object('status','noop','message','already assigned');
  end if;

  v_required := greatest(1, coalesce(v_shift.required_staff_count,1));

  -- 3) 必要枠内(1..required)で最初の空きを探索
  for v_slot_idx in 1..v_required loop
    v_curr_user_id := case v_slot_idx
                        when 1 then v_shift.staff_01_user_id
                        when 2 then v_shift.staff_02_user_id
                        else      v_shift.staff_03_user_id
                      end;
    if v_curr_user_id is null then
      v_empty_idx := v_slot_idx;
      exit;
    end if;
  end loop;

  -- 4) 置換候補（level_sort<5000000 の中で最小）を探索＆各枠の level_sort を記録
  for v_slot_idx in 1..3 loop
    v_curr_user_id := case v_slot_idx
                        when 1 then v_shift.staff_01_user_id
                        when 2 then v_shift.staff_02_user_id
                        else      v_shift.staff_03_user_id
                      end;
    if v_curr_user_id is null then
      continue;
    end if;

    select ue.level_sort::bigint into v_level_sort
      from user_entry_united_view_single ue
     where ue.user_id = v_curr_user_id
     limit 1;

    if v_level_sort is null then
      v_level_sort := 999999999; -- ID不一致/未登録は置換不可扱い
    end if;

    v_level_sorts[v_slot_idx] := v_level_sort;

    if v_level_sort < 5000000 then
      if v_lowest_sort is null or v_level_sort < v_lowest_sort then
        v_lowest_sort := v_level_sort;
        v_candidate_idx := v_slot_idx;
      end if;
    end if;
  end loop;

  -- 5) 適用（同行希望あり＝空き→置換／なし＝置換→空き）
  if p_accompany then
    if v_empty_idx > 0 then
      execute format(
        'update public.shift set %I = $1, %I = coalesce($2,%I), update_at = now() where shift_id = $3',
        v_slot_cols[v_empty_idx], v_role_cols[v_empty_idx], v_role_cols[v_empty_idx]
      ) using p_user_id, p_role_code, p_shift_id;

      v_status   := 'assigned';
      v_decision := format('accompany=true empty->%s', v_slot_names[v_empty_idx]);

      insert into public.shift_assign_log(
        shift_id, requested_user_id, accompany, required_staff_count,
        staff_01_user_id, staff_01_level_sort,
        staff_02_user_id, staff_02_level_sort,
        staff_03_user_id, staff_03_level_sort,
        empty_idx, candidate_idx, lowest_sort, decision, status, message
      ) values (
        p_shift_id, p_user_id, p_accompany, v_required,
        v_shift.staff_01_user_id, v_level_sorts[1],
        v_shift.staff_02_user_id, v_level_sorts[2],
        v_shift.staff_03_user_id, v_level_sorts[3],
        v_empty_idx, v_candidate_idx, v_lowest_sort, v_decision, v_status, null
      );

      return jsonb_build_object('status','assigned','slot',v_slot_names[v_empty_idx]);

    elsif v_candidate_idx > 0 then
      execute format(
        'update public.shift set %I = $1, %I = coalesce($2,%I), update_at = now() where shift_id = $3',
        v_slot_cols[v_candidate_idx], v_role_cols[v_candidate_idx], v_role_cols[v_candidate_idx]
      ) using p_user_id, p_role_code, p_shift_id;

      v_status   := 'replaced';
      v_decision := format('accompany=true replace->%s (lowest=%s)', v_slot_names[v_candidate_idx], v_lowest_sort);

      insert into public.shift_assign_log(
        shift_id, requested_user_id, accompany, required_staff_count,
        staff_01_user_id, staff_01_level_sort,
        staff_02_user_id, staff_02_level_sort,
        staff_03_user_id, staff_03_level_sort,
        empty_idx, candidate_idx, lowest_sort, decision, status, message
      ) values (
        p_shift_id, p_user_id, p_accompany, v_required,
        v_shift.staff_01_user_id, v_level_sorts[1],
        v_shift.staff_02_user_id, v_level_sorts[2],
        v_shift.staff_03_user_id, v_level_sorts[3],
        v_empty_idx, v_candidate_idx, v_lowest_sort, v_decision, v_status, null
      );

      return jsonb_build_object('status','replaced','slot',v_slot_names[v_candidate_idx]);

    else
      v_status   := 'error';
      v_decision := 'accompany=true no_empty no_candidate';
      v_message  := '交代できる人が見つけられないため、希望シフトを登録できませんでした。マネジャーに問い合わせください';

      insert into public.shift_assign_log(
        shift_id, requested_user_id, accompany, required_staff_count,
        staff_01_user_id, staff_01_level_sort,
        staff_02_user_id, staff_02_level_sort,
        staff_03_user_id, staff_03_level_sort,
        empty_idx, candidate_idx, lowest_sort, decision, status, message
      ) values (
        p_shift_id, p_user_id, p_accompany, v_required,
        v_shift.staff_01_user_id, v_level_sorts[1],
        v_shift.staff_02_user_id, v_level_sorts[2],
        v_shift.staff_03_user_id, v_level_sorts[3],
        v_empty_idx, v_candidate_idx, v_lowest_sort, v_decision, v_status, v_message
      );

      return jsonb_build_object('status','error','message',v_message);
    end if;

  else
    if v_candidate_idx > 0 then
      execute format(
        'update public.shift set %I = $1, %I = coalesce($2,%I), update_at = now() where shift_id = $3',
        v_slot_cols[v_candidate_idx], v_role_cols[v_candidate_idx], v_role_cols[v_candidate_idx]
      ) using p_user_id, p_role_code, p_shift_id;

      v_status   := 'replaced';
      v_decision := format('accompany=false replace->%s (lowest=%s)', v_slot_names[v_candidate_idx], v_lowest_sort);

      insert into public.shift_assign_log(
        shift_id, requested_user_id, accompany, required_staff_count,
        staff_01_user_id, staff_01_level_sort,
        staff_02_user_id, staff_02_level_sort,
        staff_03_user_id, staff_03_level_sort,
        empty_idx, candidate_idx, lowest_sort, decision, status, message
      ) values (
        p_shift_id, p_user_id, p_accompany, v_required,
        v_shift.staff_01_user_id, v_level_sorts[1],
        v_shift.staff_02_user_id, v_level_sorts[2],
        v_shift.staff_03_user_id, v_level_sorts[3],
        v_empty_idx, v_candidate_idx, v_lowest_sort, v_decision, v_status, null
      );

      return jsonb_build_object('status','replaced','slot',v_slot_names[v_candidate_idx]);

    elsif v_empty_idx > 0 then
      execute format(
        'update public.shift set %I = $1, %I = coalesce($2,%I), update_at = now() where shift_id = $3',
        v_slot_cols[v_empty_idx], v_role_cols[v_empty_idx], v_role_cols[v_empty_idx]
      ) using p_user_id, p_role_code, p_shift_id;

      v_status   := 'assigned';
      v_decision := format('accompany=false empty->%s', v_slot_names[v_empty_idx]);

      insert into public.shift_assign_log(
        shift_id, requested_user_id, accompany, required_staff_count,
        staff_01_user_id, staff_01_level_sort,
        staff_02_user_id, staff_02_level_sort,
        staff_03_user_id, staff_03_level_sort,
        empty_idx, candidate_idx, lowest_sort, decision, status, message
      ) values (
        p_shift_id, p_user_id, p_accompany, v_required,
        v_shift.staff_01_user_id, v_level_sorts[1],
        v_shift.staff_02_user_id, v_level_sorts[2],
        v_shift.staff_03_user_id, v_level_sorts[3],
        v_empty_idx, v_candidate_idx, v_lowest_sort, v_decision, v_status, null
      );

      return jsonb_build_object('status','assigned','slot',v_slot_names[v_empty_idx]);

    else
      v_status   := 'error';
      v_decision := 'accompany=false no_empty no_candidate';
      v_message  := '交代できる人が見つけられないため、希望シフトを登録できませんでした。マネジャーに問い合わせください';

      insert into public.shift_assign_log(
        shift_id, requested_user_id, accompany, required_staff_count,
        staff_01_user_id, staff_01_level_sort,
        staff_02_user_id, staff_02_level_sort,
        staff_03_user_id, staff_03_level_sort,
        empty_idx, candidate_idx, lowest_sort, decision, status, message
      ) values (
        p_shift_id, p_user_id, p_accompany, v_required,
        v_shift.staff_01_user_id, v_level_sorts[1],
        v_shift.staff_02_user_id, v_level_sorts[2],
        v_shift.staff_03_user_id, v_level_sorts[3],
        v_empty_idx, v_candidate_idx, v_lowest_sort, v_decision, v_status, v_message
      );

      return jsonb_build_object('status','error','message',v_message);
    end if;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_user_to_shift_v2(p_shift_id bigint, p_user_id text, p_role_code text DEFAULT NULL::text, p_accompany boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_shift         public.shift%rowtype;
  v_required      smallint;
  v_empty_idx     int := 0;
  v_candidate_idx int := 0;
  v_lowest_sort   bigint := null;
  v_level_sort    bigint;
  v_slot_idx      int;
  v_slot_names    text[] := array['staff_01','staff_02','staff_03'];

  -- 生値
  v_u1_raw text; v_u2_raw text; v_u3_raw text;
  v_r1_raw text; v_r2_raw text; v_r3_raw text;

  -- 正規化後（'' → NULL）
  v_u1 text; v_u2 text; v_u3 text;
  v_r1 text; v_r2 text; v_r3 text;

  v_level_sorts   bigint[] := array[NULL::bigint, NULL::bigint, NULL::bigint];
  v_decision      text := '';
  v_status        text := '';
  v_message       text := null;

  -- role_code のサニタイズ（テーブル制約対応）
  v_new_role text;
begin
  -- 0) role_code 正規化
  if p_role_code in ('01','02','-999') then
    v_new_role := p_role_code;
  else
    v_new_role := null; -- 無指定 or 無効値は変更しない方針
  end if;

  -- 1) 対象行をロック取得
  select * into v_shift from public.shift where shift_id = p_shift_id for update;
  if not found then
    v_status  := 'error';
    v_message := 'shift not found';
    insert into public.shift_assign_log(shift_id, requested_user_id, accompany, decision, status, message)
    values (p_shift_id, p_user_id, p_accompany, 'not_found', v_status, v_message);
    return jsonb_build_object('status','error','message',v_message);
  end if;

  -- 既存値を退避（生値）
  v_u1_raw := v_shift.staff_01_user_id;  v_r1_raw := v_shift.staff_01_role_code;
  v_u2_raw := v_shift.staff_02_user_id;  v_r2_raw := v_shift.staff_02_role_code;
  v_u3_raw := v_shift.staff_03_user_id;  v_r3_raw := v_shift.staff_03_role_code;

  -- '' を NULL に正規化
  v_u1 := nullif(v_u1_raw, '');  v_r1 := nullif(v_r1_raw, '');
  v_u2 := nullif(v_u2_raw, '');  v_r2 := nullif(v_r2_raw, '');
  v_u3 := nullif(v_u3_raw, '');  v_r3 := nullif(v_r3_raw, '');

  -- 2) 既に本人が入っているなら何もしない（空文字も含めた比較：正規化後でOK）
  if v_u1 = p_user_id or v_u2 = p_user_id or v_u3 = p_user_id then
    v_status   := 'noop';
    v_decision := 'already_assigned';
    insert into public.shift_assign_log(
      shift_id, requested_user_id, accompany, required_staff_count,
      staff_01_user_id, staff_02_user_id, staff_03_user_id,
      empty_idx, candidate_idx, lowest_sort, decision, status, message
    ) values (
      p_shift_id, p_user_id, p_accompany, v_shift.required_staff_count,
      v_u1, v_u2, v_u3,
      0, 0, null, v_decision, v_status, 'already assigned'
    );
    return jsonb_build_object('status','noop','message','already assigned');
  end if;

  v_required := greatest(1, coalesce(v_shift.required_staff_count,1));

  -- 3) 必要枠内(1..required)で最初の空きを探索（'' も空き扱い → 正規化済みを判定）
  for v_slot_idx in 1..v_required loop
    if (v_slot_idx = 1 and v_u1 is null)
       or (v_slot_idx = 2 and v_u2 is null)
       or (v_slot_idx = 3 and v_u3 is null)
    then
      v_empty_idx := v_slot_idx;
      exit;
    end if;
  end loop;

  -- 4) 置換候補（level_sort<5000000 の中で最小）を探索＆各枠の level_sort を記録
  for v_slot_idx in 1..3 loop
    if (v_slot_idx = 1 and v_u1 is null)
       or (v_slot_idx = 2 and v_u2 is null)
       or (v_slot_idx = 3 and v_u3 is null)
    then
      continue;
    end if;

    select ue.level_sort::bigint into v_level_sort
      from public.user_entry_united_view_single ue
     where ue.user_id = case v_slot_idx when 1 then v_u1 when 2 then v_u2 else v_u3 end
     limit 1;

    if v_level_sort is null then
      v_level_sort := 999999999; -- 未登録は置換不可扱い
    end if;

    v_level_sorts[v_slot_idx] := v_level_sort;

    if v_level_sort < 5000000 then
      -- attend フラグ制御（02/03 は false の時だけ候補可）
      if v_slot_idx = 1
         or (v_slot_idx = 2 and coalesce(v_shift.staff_02_attend_flg,false) = false)
         or (v_slot_idx = 3 and coalesce(v_shift.staff_03_attend_flg,false) = false)
      then
        if v_lowest_sort is null or v_level_sort < v_lowest_sort then
          v_lowest_sort   := v_level_sort;
          v_candidate_idx := v_slot_idx;
        end if;
      end if;
    end if;
  end loop;

  -- 5) 適用
  if p_accompany then
    -- 5-1) 空きがあればそこに入れる（後ろずらしなし → attend_flg 変更なし）
    if v_empty_idx > 0 then
      if v_empty_idx = 1 then
        update public.shift
           set staff_01_user_id  = p_user_id,
               staff_01_role_code= coalesce(v_new_role, staff_01_role_code),
               update_at         = now()
         where shift_id = p_shift_id;
      elsif v_empty_idx = 2 then
        update public.shift
           set staff_02_user_id  = p_user_id,
               staff_02_role_code= coalesce(v_new_role, staff_02_role_code),
               update_at         = now()
         where shift_id = p_shift_id;
      else
        update public.shift
           set staff_03_user_id  = p_user_id,
               staff_03_role_code= coalesce(v_new_role, staff_03_role_code),
               update_at         = now()
         where shift_id = p_shift_id;
      end if;

      v_status   := 'assigned';
      v_decision := format('accompany=true empty->%s', v_slot_names[v_empty_idx]);

      insert into public.shift_assign_log(
        shift_id, requested_user_id, accompany, required_staff_count,
        staff_01_user_id, staff_01_level_sort,
        staff_02_user_id, staff_02_level_sort,
        staff_03_user_id, staff_03_level_sort,
        empty_idx, candidate_idx, lowest_sort, decision, status, message
      ) values (
        p_shift_id, p_user_id, p_accompany, v_required,
        v_u1, v_level_sorts[1],
        v_u2, v_level_sorts[2],
        v_u3, v_level_sorts[3],
        v_empty_idx, 0, null, v_decision, v_status, null
      );

      return jsonb_build_object('status','assigned','slot',v_slot_names[v_empty_idx]);
    end if;

    -- 5-2) 空きが無い → 最小 level_sort の枠を置換。
    --       このとき “押し出されたユーザー” を下位枠へずらし、ずらされた枠の attend_flg を true にする
    if v_candidate_idx > 0 then
      if v_candidate_idx = 1 then
        -- 01 をリクエスト者に、旧01 を 02/03 へ“ずらす”
        if v_u2 is null then
          -- 01 -> 02 にスライド（02 attend=true）
          update public.shift
             set staff_01_user_id   = p_user_id,
                 staff_01_role_code = coalesce(v_new_role, staff_01_role_code),
                 staff_02_user_id   = v_u1,
                 staff_02_role_code = v_r1,
                 staff_02_attend_flg= true,
                 update_at          = now()
           where shift_id = p_shift_id;
          v_decision := 'accompany=true replace->staff_01 (demote 01->02, attend_02=true)';
        elsif v_u3 is null then
          -- 02 -> 03 にスライド（03 attend=true）、01 -> 02 にスライド（02 attend=true）
          update public.shift
             set staff_01_user_id   = p_user_id,
                 staff_01_role_code = coalesce(v_new_role, staff_01_role_code),
                 staff_03_user_id   = v_u2,
                 staff_03_role_code = v_r2,
                 staff_03_attend_flg= true,
                 staff_02_user_id   = v_u1,
                 staff_02_role_code = v_r1,
                 staff_02_attend_flg= true,
                 update_at          = now()
           where shift_id = p_shift_id;
          v_decision := 'accompany=true replace->staff_01 (demote 02->03 & 01->02, attend_02/03=true)';
        else
          -- 下位に空きが無ければ“ずらせない”ので、ノーデモート（従来挙動）
          update public.shift
             set staff_01_user_id   = p_user_id,
                 staff_01_role_code = coalesce(v_new_role, staff_01_role_code),
                 update_at          = now()
           where shift_id = p_shift_id;
          v_decision := 'accompany=true replace->staff_01 (no demote)';
        end if;

      elsif v_candidate_idx = 2 then
        -- 02 をリクエスト者に、旧02 を 03 へ“ずらす”（03 attend=true）※03 が空いている場合のみ
        if v_u3 is null then
          update public.shift
             set staff_02_user_id   = p_user_id,
                 staff_02_role_code = coalesce(v_new_role, staff_02_role_code),
                 staff_03_user_id   = v_u2,
                 staff_03_role_code = v_r2,
                 staff_03_attend_flg= true,
                 update_at          = now()
           where shift_id = p_shift_id;
          v_decision := 'accompany=true replace->staff_02 (demote 02->03, attend_03=true)';
        else
          -- 03も埋まっているなら“ずらせない” → ノーデモートで 02 に入れるだけ
          update public.shift
             set staff_02_user_id   = p_user_id,
                 staff_02_role_code = coalesce(v_new_role, staff_02_role_code),
                 update_at          = now()
           where shift_id = p_shift_id;
          v_decision := 'accompany=true replace->staff_02 (no demote)';
        end if;

      else
        -- accompany=true で 03 候補 → 下位が無いのでノーデモート
        update public.shift
           set staff_03_user_id   = p_user_id,
               staff_03_role_code = coalesce(v_new_role, staff_03_role_code),
               update_at          = now()
         where shift_id = p_shift_id;
        v_decision := 'accompany=true replace->staff_03 (no demote)';
      end if;

      v_status := 'replaced';

      insert into public.shift_assign_log(
        shift_id, requested_user_id, accompany, required_staff_count,
        staff_01_user_id, staff_01_level_sort,
        staff_02_user_id, staff_02_level_sort,
        staff_03_user_id, staff_03_level_sort,
        empty_idx, candidate_idx, lowest_sort, decision, status, message
      ) values (
        p_shift_id, p_user_id, p_accompany, v_required,
        v_u1, v_level_sorts[1],
        v_u2, v_level_sorts[2],
        v_u3, v_level_sorts[3],
        v_empty_idx, v_candidate_idx, v_lowest_sort, v_decision, v_status, null
      );

      return jsonb_build_object('status','replaced','slot',v_slot_names[v_candidate_idx]);
    end if;

    -- 空きも候補もない
    v_status   := 'error';
    v_decision := 'accompany=true no_empty no_candidate';
    v_message  := '交代できる人が見つけられないため、希望シフトを登録できませんでした。マネジャーに問い合わせください';

    insert into public.shift_assign_log(
      shift_id, requested_user_id, accompany, required_staff_count,
      staff_01_user_id, staff_01_level_sort,
      staff_02_user_id, staff_02_level_sort,
      staff_03_user_id, staff_03_level_sort,
      empty_idx, candidate_idx, lowest_sort, decision, status, message
    ) values (
      p_shift_id, p_user_id, p_accompany, v_required,
      v_u1, v_level_sorts[1],
      v_u2, v_level_sorts[2],
      v_u3, v_level_sorts[3],
      v_empty_idx, v_candidate_idx, v_lowest_sort, v_decision, v_status, v_message
    );

    return jsonb_build_object('status','error','message',v_message);

  else
    -- accompany=false（ずらし不要）: attend_flg 変更なし
    if v_candidate_idx > 0 then
      if v_candidate_idx = 1 then
        update public.shift
           set staff_01_user_id   = p_user_id,
               staff_01_role_code = coalesce(v_new_role, staff_01_role_code),
               update_at          = now()
         where shift_id = p_shift_id;
      elsif v_candidate_idx = 2 then
        update public.shift
           set staff_02_user_id   = p_user_id,
               staff_02_role_code = coalesce(v_new_role, staff_02_role_code),
               update_at          = now()
         where shift_id = p_shift_id;
      else
        update public.shift
           set staff_03_user_id   = p_user_id,
               staff_03_role_code = coalesce(v_new_role, staff_03_role_code),
               update_at          = now()
         where shift_id = p_shift_id;
      end if;

      v_status   := 'replaced';
      v_decision := format('accompany=false replace->%s (no demote)', v_slot_names[v_candidate_idx]);

      insert into public.shift_assign_log(
        shift_id, requested_user_id, accompany, required_staff_count,
        staff_01_user_id, staff_01_level_sort,
        staff_02_user_id, staff_02_level_sort,
        staff_03_user_id, staff_03_level_sort,
        empty_idx, candidate_idx, lowest_sort, decision, status, message
      ) values (
        p_shift_id, p_user_id, p_accompany, v_required,
        v_u1, v_level_sorts[1],
        v_u2, v_level_sorts[2],
        v_u3, v_level_sorts[3],
        v_empty_idx, v_candidate_idx, v_lowest_sort, v_decision, v_status, null
      );

      return jsonb_build_object('status','replaced','slot',v_slot_names[v_candidate_idx]);

    elsif v_empty_idx > 0 then
      if v_empty_idx = 1 then
        update public.shift
           set staff_01_user_id   = p_user_id,
               staff_01_role_code = coalesce(v_new_role, staff_01_role_code),
               update_at          = now()
         where shift_id = p_shift_id;
      elsif v_empty_idx = 2 then
        update public.shift
           set staff_02_user_id   = p_user_id,
               staff_02_role_code = coalesce(v_new_role, staff_02_role_code),
               update_at          = now()
         where shift_id = p_shift_id;
      else
        update public.shift
           set staff_03_user_id   = p_user_id,
               staff_03_role_code = coalesce(v_new_role, staff_03_role_code),
               update_at          = now()
         where shift_id = p_shift_id;
      end if;

      v_status   := 'assigned';
      v_decision := format('accompany=false empty->%s', v_slot_names[v_empty_idx]);

      insert into public.shift_assign_log(
        shift_id, requested_user_id, accompany, required_staff_count,
        staff_01_user_id, staff_01_level_sort,
        staff_02_user_id, staff_02_level_sort,
        staff_03_user_id, staff_03_level_sort,
        empty_idx, candidate_idx, lowest_sort, decision, status, message
      ) values (
        p_shift_id, p_user_id, p_accompany, v_required,
        v_u1, v_level_sorts[1],
        v_u2, v_level_sorts[2],
        v_u3, v_level_sorts[3],
        v_empty_idx, 0, null, v_decision, v_status, null
      );

      return jsonb_build_object('status','assigned','slot',v_slot_names[v_empty_idx]);

    else
      v_status   := 'error';
      v_decision := 'accompany=false no_empty no_candidate';
      v_message  := '交代できる人が見つけられないため、希望シフトを登録できませんでした。マネジャーに問い合わせください';

      insert into public.shift_assign_log(
        shift_id, requested_user_id, accompany, required_staff_count,
        staff_01_user_id, staff_01_level_sort,
        staff_02_user_id, staff_02_level_sort,
        staff_03_user_id, staff_03_level_sort,
        empty_idx, candidate_idx, lowest_sort, decision, status, message
      ) values (
        p_shift_id, p_user_id, p_accompany, v_required,
        v_u1, v_level_sorts[1],
        v_u2, v_level_sorts[2],
        v_u3, v_level_sorts[3],
        v_empty_idx, v_candidate_idx, v_lowest_sort, v_decision, v_status, v_message
      );

      return jsonb_build_object('status','error','message',v_message);
    end if;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.batch_reassign_departed_staff_shifts(p_actor_auth_id uuid, p_start_at timestamp without time zone, p_from_user_id text, p_to_user_id text)
 RETURNS TABLE(processed_count integer, updated_count integer, deleted_count integer, failed_count integer, weekly_processed_count integer, weekly_updated_count integer, weekly_deleted_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_shift public.shift%rowtype;
  v_template public.shift_weekly_template%rowtype;
  v_entries jsonb;
  v_next jsonb;
  v_entry jsonb;
  v_user_id text;
  v_seen text[] := array[]::text[];
  v_target_exists boolean;
  v_count integer;
  v_updated integer := 0;
  v_deleted integer := 0;
  v_processed integer := 0;
  v_weekly_processed integer := 0;
  v_weekly_updated integer := 0;
  v_weekly_deleted integer := 0;
begin
  if p_start_at is null or nullif(btrim(p_from_user_id), '') is null or nullif(btrim(p_to_user_id), '') is null then
    raise exception '開始日時、変更元スタッフ、変更先スタッフは必須です';
  end if;
  if btrim(p_from_user_id) = btrim(p_to_user_id) then
    raise exception '変更元スタッフと変更先スタッフは異なるスタッフを指定してください';
  end if;
  if not exists (
    select 1 from public.users u
    where u.auth_user_id::text = p_actor_auth_id::text
      and lower(coalesce(u.system_role, '')) in ('manager', 'admin')
  ) then
    raise exception 'この操作を実行する権限がありません';
  end if;

  for v_shift in
    select s.*
    from public.shift s
    where (s.shift_start_date::date + coalesce(s.shift_start_time::time, time '00:00')) >= p_start_at
      and btrim(p_from_user_id) in (
        nullif(btrim(s.staff_01_user_id), ''), nullif(btrim(s.staff_02_user_id), ''), nullif(btrim(s.staff_03_user_id), '')
      )
    for update
  loop
    v_processed := v_processed + 1;
    v_entries := jsonb_build_array(
      jsonb_build_object('user_id', nullif(btrim(v_shift.staff_01_user_id), ''), 'role_code', v_shift.staff_01_role_code, 'attend_flg', false),
      jsonb_build_object('user_id', nullif(btrim(v_shift.staff_02_user_id), ''), 'role_code', v_shift.staff_02_role_code, 'attend_flg', coalesce(v_shift.staff_02_attend_flg, false)),
      jsonb_build_object('user_id', nullif(btrim(v_shift.staff_03_user_id), ''), 'role_code', v_shift.staff_03_role_code, 'attend_flg', coalesce(v_shift.staff_03_attend_flg, false))
    );
    v_target_exists := exists (
      select 1 from jsonb_array_elements(v_entries) e
      where e->>'user_id' = btrim(p_to_user_id)
    );
    v_next := '[]'::jsonb;
    v_seen := array[]::text[];
    for v_entry in select value from jsonb_array_elements(v_entries)
    loop
      v_user_id := v_entry->>'user_id';
      if v_user_id is null then
        continue;
      end if;
      -- A replacement that would duplicate an existing assignee removes the
      -- departing slot.  All remaining entries are then compacted in order.
      if v_user_id = btrim(p_from_user_id) then
        if v_target_exists then
          continue;
        end if;
        v_entry := jsonb_set(v_entry, '{user_id}', to_jsonb(btrim(p_to_user_id)));
        v_user_id := btrim(p_to_user_id);
      end if;
      if v_user_id = any(v_seen) then
        continue;
      end if;
      v_seen := array_append(v_seen, v_user_id);
      v_next := v_next || jsonb_build_array(v_entry);
    end loop;
    v_count := jsonb_array_length(v_next);
    if v_count = 0 then
      delete from public.shift where shift_id = v_shift.shift_id;
      v_deleted := v_deleted + 1;
    else
      update public.shift s set
        staff_01_user_id = v_next->0->>'user_id',
        staff_01_role_code = v_next->0->>'role_code',
        staff_02_user_id = case when v_count >= 2 then v_next->1->>'user_id' else null end,
        staff_02_role_code = case when v_count >= 2 then v_next->1->>'role_code' else null end,
        staff_02_attend_flg = case when v_count >= 2 then coalesce((v_next->1->>'attend_flg')::boolean, false) else false end,
        staff_03_user_id = case when v_count >= 3 then v_next->2->>'user_id' else null end,
        staff_03_role_code = case when v_count >= 3 then v_next->2->>'role_code' else null end,
        staff_03_attend_flg = case when v_count >= 3 then coalesce((v_next->2->>'attend_flg')::boolean, false) else false end,
        update_at = now()
      where s.shift_id = v_shift.shift_id;
      v_updated := v_updated + 1;
    end if;
  end loop;

  -- Weekly templates create future shifts.  Only active templates which can
  -- still produce a shift on/after the start date are changed in this same
  -- transaction; an expired or inactive template remains historical data.
  for v_template in
    select t.*
    from public.shift_weekly_template t
    where t.active
      and (t.effective_to is null or t.effective_to::date >= p_start_at::date)
      and btrim(p_from_user_id) in (
        nullif(btrim(t.staff_01_user_id), ''), nullif(btrim(t.staff_02_user_id), ''), nullif(btrim(t.staff_03_user_id), '')
      )
    for update
  loop
    v_weekly_processed := v_weekly_processed + 1;
    v_entries := jsonb_build_array(
      jsonb_build_object('user_id', nullif(btrim(v_template.staff_01_user_id), ''), 'role_code', v_template.staff_01_role_code, 'attend_flg', false),
      jsonb_build_object('user_id', nullif(btrim(v_template.staff_02_user_id), ''), 'role_code', v_template.staff_02_role_code, 'attend_flg', coalesce(v_template.staff_02_attend_flg, false)),
      jsonb_build_object('user_id', nullif(btrim(v_template.staff_03_user_id), ''), 'role_code', v_template.staff_03_role_code, 'attend_flg', coalesce(v_template.staff_03_attend_flg, false))
    );
    v_target_exists := exists (select 1 from jsonb_array_elements(v_entries) e where e->>'user_id' = btrim(p_to_user_id));
    v_next := '[]'::jsonb;
    v_seen := array[]::text[];
    for v_entry in select value from jsonb_array_elements(v_entries)
    loop
      v_user_id := v_entry->>'user_id';
      if v_user_id is null then continue; end if;
      if v_user_id = btrim(p_from_user_id) then
        if v_target_exists then continue; end if;
        v_entry := jsonb_set(v_entry, '{user_id}', to_jsonb(btrim(p_to_user_id)));
        v_user_id := btrim(p_to_user_id);
      end if;
      if v_user_id = any(v_seen) then continue; end if;
      v_seen := array_append(v_seen, v_user_id);
      v_next := v_next || jsonb_build_array(v_entry);
    end loop;
    v_count := jsonb_array_length(v_next);
    if v_count = 0 then
      delete from public.shift_weekly_template where template_id = v_template.template_id;
      v_weekly_deleted := v_weekly_deleted + 1;
    else
      update public.shift_weekly_template t set
        staff_01_user_id = v_next->0->>'user_id',
        staff_01_role_code = v_next->0->>'role_code',
        staff_02_user_id = case when v_count >= 2 then v_next->1->>'user_id' else null end,
        staff_02_role_code = case when v_count >= 2 then v_next->1->>'role_code' else null end,
        staff_02_attend_flg = case when v_count >= 2 then coalesce((v_next->1->>'attend_flg')::boolean, false) else false end,
        staff_03_user_id = case when v_count >= 3 then v_next->2->>'user_id' else null end,
        staff_03_role_code = case when v_count >= 3 then v_next->2->>'role_code' else null end,
        staff_03_attend_flg = case when v_count >= 3 then coalesce((v_next->2->>'attend_flg')::boolean, false) else false end
      where t.template_id = v_template.template_id;
      v_weekly_updated := v_weekly_updated + 1;
    end if;
  end loop;
  return query select v_processed, v_updated, v_deleted, 0, v_weekly_processed, v_weekly_updated, v_weekly_deleted;
end;
$function$

CREATE OR REPLACE FUNCTION public.classify_cs_doc_label(p_text text, p_current_label text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  r record;
  v_best_label text := null;
  v_best_score int := -1;
  v_score int;
  v_text text := public.normalize_jp_text(coalesce(p_text, '') || ' ' || coalesce(p_current_label, ''));
  v_logic text;
  v_tokens text[];
  v_token text;
begin
  -- 既存ラベルが正規ラベルならそのまま返す
  if exists (
    select 1
    from user_doc_master udm
    where udm.category = 'cs_doc'
      and udm.label = p_current_label
  ) then
    return p_current_label;
  end if;

  for r in
    select label, judge_logic
    from user_doc_master
    where category = 'cs_doc'
      and coalesce(label, '') <> ''
  loop
    v_score := 0;
    v_logic := coalesce(r.judge_logic, '');

    -- label 自体の一致は強め
    if v_text like '%' || public.normalize_jp_text(r.label) || '%' then
      v_score := v_score + 100;
    end if;

    -- judge_logic を雑に token 化してスコアリング
    v_tokens := regexp_split_to_array(v_logic, E'[,\n\r|、/]+');

    if v_tokens is not null then
      foreach v_token in array v_tokens
      loop
        v_token := btrim(v_token);
        if v_token <> '' and v_text like '%' || public.normalize_jp_text(v_token) || '%' then
          v_score := v_score + 10;
        end if;
      end loop;
    end if;

    if v_score > v_best_score then
      v_best_score := v_score;
      v_best_label := r.label;
    end if;
  end loop;

  if v_best_score >= 10 then
    return v_best_label;
  end if;

  return '分類不能';
end;
$function$

CREATE OR REPLACE FUNCTION public.cm_contract_update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.cron_alert_dedupe_and_recalc()
 RETURNS TABLE(deleted_count integer, updated_count integer)
 LANGUAGE plpgsql
AS $function$
declare
  v_deleted int := 0;
  v_updated int := 0;
  v_rc int := 0;
begin
  /*
    ① 同じ message が複数あれば、新しいものを削除
       （created_at が最も古い1件だけ残す）
  */
  with ranked as (
    select
      id,
      row_number() over (
        partition by message
        order by created_at asc, id asc
      ) as rn
    from public.alert_log
  )
  delete from public.alert_log a
  using ranked r
  where a.id = r.id
    and r.rn > 1;

  get diagnostics v_deleted = row_count;

  /*
    ② 重複があった message の「最古の1件」を open + system に戻す
      ※ auto_done cron が .in(status_source, ['system']) なので合わせる
  */
  with ranked as (
    select
      id,
      row_number() over (
        partition by message
        order by created_at asc, id asc
      ) as rn,
      count(*) over (partition by message) as grp_cnt
    from public.alert_log
  )
  update public.alert_log a
     set status = 'open',
         status_source = 'system',
         updated_at = now()
    from ranked r
   where a.id = r.id
     and r.grp_cnt > 1
     and r.rn = 1
     and (
       a.status is distinct from 'open'
       or a.status_source is distinct from 'system'
     );

  get diagnostics v_rc = row_count;
  v_updated := v_updated + v_rc;

  /*
    ③ created_at から 2日で +1Lv の severity 再計算（最大5）
       base=2
  */
  update public.alert_log
     set severity = least(
                    5,
                    2 + floor(
                          extract(epoch from (now() - created_at))
                          / 86400 / 2
                        )::int
                  ),
         updated_at = now()
   where severity is distinct from least(
                    5,
                    2 + floor(
                          extract(epoch from (now() - created_at))
                          / 86400 / 2
                        )::int
                  );

  get diagnostics v_rc = row_count;
  v_updated := v_updated + v_rc;

  return query select v_deleted, v_updated;
end $function$

CREATE OR REPLACE FUNCTION public.extract_doc_date_raw(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v text;
begin
  if p_text is null or btrim(p_text) = '' then
    return null;
  end if;

  -- 優先: 契約日 / 作成日 / 交付日 / 発行日 / FAX送付日
  select (regexp_match(
    p_text,
    '(契約日|作成日|交付日|発行日|FAX送付日|送付日)[^0-9０-９令和平成昭和]{0,10}([令和平成昭和]?[0-9０-９]{1,4}[年/\.-][0-9０-９]{1,2}[月/\.-][0-9０-９]{1,2}日?)'
  ))[2]
  into v;

  if v is not null then
    return v;
  end if;

  -- fallback: 最初の日付
  select (regexp_match(
    p_text,
    '([令和平成昭和]?[0-9０-９]{1,4}[年/\.-][0-9０-９]{1,2}[月/\.-][0-9０-９]{1,2}日?)'
  ))[1]
  into v;

  return v;
end;
$function$

CREATE OR REPLACE FUNCTION public.extract_drive_file_id(p_url text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_id text;
begin
  if p_url is null or btrim(p_url) = '' then
    return null;
  end if;

  -- https://drive.google.com/file/d/<ID>/view
  v_id := substring(p_url from '/d/([^/]+)');
  if v_id is not null then
    return v_id;
  end if;

  -- https://drive.google.com/uc?export=view&id=<ID>
  v_id := substring(p_url from 'id=([^&]+)');
  if v_id is not null then
    return v_id;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.extract_user_name_raw(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v text;
begin
  if p_text is null or btrim(p_text) = '' then
    return null;
  end if;

  -- 利用者名 / 氏名 / 対象者
  select coalesce(
    (regexp_match(p_text, '(利用者名|氏名|対象者)[:： 　]*([^\r\n　 ]{1,30}(?:[ 　][^\r\n　 ]{1,30})?)'))[2],
    (regexp_match(p_text, '([^\r\n　 ]{1,30}(?:[ 　][^\r\n　 ]{1,30})?)\s*様'))[1]
  )
  into v;

  return nullif(btrim(v), '');
end;
$function$

