CREATE OR REPLACE FUNCTION public.normalize_shift_before_payroll_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_cancel_item uuid := '2bd7eefb-3fb6-47fe-8684-1ac6f3ec530a'::uuid;
  v_fix_end_date int := 0;
  v_mark_cancel  int := 0;
  v_align_time   int := 0;
begin
  update public.shift s
     set shift_end_date = s.shift_start_date
   where s.shift_end_date is null
     and s.shift_start_date is not null;
  get diagnostics v_fix_end_date = row_count;

  with canceled_shift as (
    select distinct s.shift_id
    from public.shift s
    join public.shift_records sr on sr.shift_id = s.shift_id
    join public.shift_record_items sri on sri.record_id = sr.id
    where sri.item_def_id = v_cancel_item
      and coalesce(sri.value_text, '1') <> '0'
  )
  update public.shift s
     set service_code = 'キャンセル（手当発生・請求有）'
   where s.shift_id in (select shift_id from canceled_shift)
     and (s.service_code is null or s.service_code not ilike '%キャンセル%');
  get diagnostics v_mark_cancel = row_count;

  update public.shift s
     set shift_end_time = s.shift_start_time
   where s.service_code ilike '%キャンセル%'
     and s.shift_start_time is not null
     and (s.shift_end_time is distinct from s.shift_start_time);
  get diagnostics v_align_time = row_count;

  return jsonb_build_object(
    'fixed_end_date_rows', v_fix_end_date,
    'marked_cancel_rows',  v_mark_cancel,
    'aligned_time_rows',   v_align_time
  );
end; $function$

CREATE OR REPLACE FUNCTION public.pick_best_kaipoke_cs_id(p_name text, p_text text, p_doc_date_raw text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  r record;
  v_best_id text := null;
  v_best_score int := -1;
  v_score int;
  v_name_norm text := public.normalize_jp_text(p_name);
  v_text_norm text := public.normalize_jp_text(p_text);
begin
  if coalesce(v_name_norm, '') = '' then
    return null;
  end if;

  for r in
    select
      cki.id,
      cki.kaipoke_cs_id,
      cki.name,
      cki.kana,
      cki.birth_yyyy_mm_dd,
      cki.kaigo_start_at,
      cki.kaigo_end_at
    from cs_kaipoke_info cki
    where cki.is_active = true
  loop
    v_score := 0;

    if public.normalize_jp_text(r.name) = v_name_norm then
      v_score := v_score + 100;
    elsif public.normalize_jp_text(r.name) <> '' and v_text_norm like '%' || public.normalize_jp_text(r.name) || '%' then
      v_score := v_score + 50;
    end if;

    if coalesce(r.kana, '') <> '' and v_text_norm like '%' || public.normalize_jp_text(r.kana) || '%' then
      v_score := v_score + 20;
    end if;

    -- date がある場合は介護開始日レンジで軽く加点
    if p_doc_date_raw is not null and coalesce(r.kaigo_start_at::text, '') <> '' then
      v_score := v_score + 5;
    end if;

    if v_score > v_best_score then
      v_best_score := v_score;
      v_best_id := r.kaipoke_cs_id;
    end if;
  end loop;

  if v_best_score >= 50 then
    return v_best_id;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.roster_patch_shift_with_context(p_shift_id bigint, p_date date, p_start time without time zone, p_end time without time zone, p_update_at timestamp without time zone, p_target_col text, p_staff_id text, p_actor_user_id text DEFAULT NULL::text, p_request_path text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  col text;
  sql text;
begin
  perform set_config('app.actor_user_id', coalesce(p_actor_user_id,''), true);
  perform set_config('app.request_path', coalesce(p_request_path,''), true);

  if p_target_col is null or p_target_col = '' then
    col := null;
  elsif p_target_col in ('staff_01_user_id','staff_02_user_id','staff_03_user_id') then
    col := p_target_col;
  else
    raise exception 'invalid target_col: %', p_target_col;
  end if;

  if col is null then
    update public.shift
    set
      shift_start_date = p_date,
      shift_start_time = p_start,
      shift_end_time   = p_end,
      update_at        = p_update_at
    where shift_id = p_shift_id;
    return;
  end if;

  sql := format($f$
    update public.shift
    set
      shift_start_date = $1,
      shift_start_time = $2,
      shift_end_time   = $3,
      update_at        = $4,
      %I              = $5
    where shift_id = $6
  $f$, col);

  execute sql using p_date, p_start, p_end, p_update_at, p_staff_id, p_shift_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_page_order_and_rotation(p_fax_received_id bigint, p_page_orders jsonb, p_assigned_by character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_page JSONB;
  v_updated_count INT := 0;
BEGIN
  IF p_page_orders IS NULL OR jsonb_array_length(p_page_orders) = 0 THEN
    RETURN jsonb_build_object('success', TRUE, 'updated_count', 0);
  END IF;
  
  FOR v_page IN SELECT * FROM jsonb_array_elements(p_page_orders)
  LOOP
    UPDATE cm_fax_pages
    SET 
      logical_order = (v_page->>'logical_order')::INT,
      rotation_confirmed = COALESCE((v_page->>'rotation')::INT, 0),
      rotation_confirmed_by = p_assigned_by,
      rotation_confirmed_at = NOW(),
      updated_at = NOW()
    WHERE id = (v_page->>'page_id')::BIGINT
      AND fax_received_id = p_fax_received_id;
    
    IF FOUND THEN
      v_updated_count := v_updated_count + 1;
    END IF;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', TRUE,
    'fax_received_id', p_fax_received_id,
    'updated_count', v_updated_count
  );
END;
$function$

