CREATE OR REPLACE FUNCTION public.update_other_office_fax_normalized()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- fax の正規化（既存処理）
  IF NEW.fax IS NOT NULL THEN
    NEW.fax_normalized = REGEXP_REPLACE(NEW.fax, '[-\s]', '', 'g');
  ELSE
    NEW.fax_normalized = NULL;
  END IF;
  
  -- fax_proxy の正規化（追加）
  IF NEW.fax_proxy IS NOT NULL THEN
    NEW.fax_proxy_normalized = REGEXP_REPLACE(NEW.fax_proxy, '[-\s]', '', 'g');
  ELSE
    NEW.fax_proxy_normalized = NULL;
  END IF;
  
  RETURN NEW;
END;
$function$

